const size_t RelUnitsCount = 432;

const char *RelStr(int32_t idx)
{
    if (idx < 0 || (size_t)idx >= RelStringCount) {
        return "";
    }
    return RelStrings[idx];
}

const RelUnit *RelUnitFind(const char *locale, uint8_t unit, uint8_t width)
{
    size_t lo = 0;
    size_t hi = RelUnitsCount;
    if (!locale) {
        return NULL;
    }
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2u;
        const RelUnit *row = &RelUnits[mid];
        int cmp = strcmp(RelStrings[row->locale], locale);
        if (cmp == 0) {
            if (row->unit == unit) {
                if (row->width == width) {
                    return row;
                }
                cmp = row->width < width ? -1 : 1;
            } else {
                cmp = row->unit < unit ? -1 : 1;
            }
        }
        if (cmp < 0) {
            lo = mid + 1u;
        } else {
            hi = mid;
        }
    }
    return NULL;
}

